//! Trait for declaring nestable modules.
//!
//! Modules group processors and menu metadata. They are usually not implemented by hand;
//! instead, apply the [`runbot_codegen::module`] attribute macro to
//! `impl Module for YourMod {}`. The macro generates default implementations of `id`,
//! `name`, `help`, and `processors`, plus the `Into<Processor>` conversion.

use async_trait::async_trait;

use crate::process::Processor;

/// Describes a module that can be registered as a processor.
///
/// Implementors are usually empty structs generated by the `#[module]` macro, along with a
/// static instance. Every method is an associated function without `self`, so module
/// metadata is fixed at compile time and cannot vary per instance at runtime.
#[async_trait]
pub trait Module {
    /// Returns the stable identifier of the module.
    ///
    /// `#[module]` generates `crate name::module path::struct name` by default. If `id` is
    /// written manually in the impl block, the macro preserves that implementation.
    fn id() -> &'static str;

    /// Returns the module name shown in menus.
    ///
    /// Defaults to the struct name. Override it with `#[module(name = "...")]`, or write
    /// `name` manually in the impl block. The attribute and a manual implementation cannot
    /// be used together.
    fn name() -> &'static str;

    /// Returns the help text shown in menus.
    ///
    /// Defaults to the struct name. Override it with `#[module(help = "...")]`, or write
    /// `help` manually in the impl block. The attribute and a manual implementation cannot
    /// be used together.
    fn help() -> &'static str;

    /// Returns the processors contained in this module.
    ///
    /// Defaults to an empty list. Specify processors with
    /// `#[module(processors = "...")]`, or override this method manually. The list order is
    /// the event dispatch order inside the module.
    fn processors() -> Vec<Processor>;
}
